'use strict';
const Network={stale:false,init(){const pill=document.createElement('span');pill.className='network-pill';pill.id='network-status';pill.setAttribute('role','status');document.querySelector('.top-actions').append(pill);const warning=document.createElement('section');warning.className='stock-freshness-warning';warning.id='stock-freshness-warning';warning.hidden=true;warning.setAttribute('role','status');warning.innerHTML='<span>连接中断后，页面已显示数据仅供参考，不是实时库存。</span><button id="refresh-live-stock" class="button secondary">重新联网查询库存</button>';document.querySelector('.topbar').after(warning);$('refresh-live-stock').onclick=async e=>{e.target.disabled=true;try{if(location.pathname==='/stock-map'){await StockMap.open();this.stale=false;update();return;}await render();await Dashboard.refresh();if(serviceReady&&Dashboard.snapshot){this.stale=false;update();}else notify('未联网查询到实时库存');}catch(e){notify(e.message);}finally{e.target.disabled=false;}};const panel=document.createElement('section');panel.className='operation-panel';panel.hidden=true;panel.id='operation-panel';panel.setAttribute('aria-live','polite');document.body.append(panel);const update=()=>{pill.textContent=(navigator.onLine?'在线':'离线')+' · '+(API.lastServerResponse?'最近服务器响应 '+API.lastServerResponse:'客户端连接提示不代表服务器可用');pill.classList.toggle('error',!navigator.onLine);warning.hidden=!this.stale;document.body.classList.toggle('stock-stale',this.stale);this.render();};window.addEventListener('online',update);window.addEventListener('offline',()=>{this.stale=true;update();});window.addEventListener('stock-stale',()=>{this.stale=true;update();});window.addEventListener('server-response',update);window.addEventListener('operation-state',()=>this.render());window.addEventListener('session-expired',()=>{panel.hidden=true;});API.restoreReceipts();update();},render(){const panel=$('operation-panel');if(!panel||!window.AppSignedIn)return;const rows=[...API.operations.values()].filter(o=>o.user_id===CurrentUser.id&&['UNKNOWN','SUBMITTING'].includes(o.state));panel.hidden=!rows.length;panel.replaceChildren();for(const o of rows.slice(-3)){const row=document.createElement('div'),text=document.createElement('p');text.textContent=(o.state==='UNKNOWN'?'提交状态未知':'提交中')+' · '+o.method+' '+o.path;row.append(text);if(o.state==='UNKNOWN'){const check=document.createElement('button');check.textContent='重新查询操作结果';check.onclick=async()=>{check.disabled=true;try{const r=await API.check(o.key);notify(r.notice);if(r.committed)await render();}catch(e){notify(e.message);}finally{check.disabled=false;}};row.append(check);if(o.options){const retry=document.createElement('button');retry.textContent='使用原请求重试';retry.onclick=async()=>{retry.disabled=true;try{await API.retry(o.key);notify('服务器已确认');await render();}catch(e){notify(e.message);}finally{retry.disabled=false;}};row.append(retry);}const hint=document.createElement('small');hint.textContent='请勿另建相同单据。只保留查询凭据，不缓存库存或离线自动提交。';row.append(hint);}panel.append(row);}}};Network.init();
